#!/usr/bin/env node
/*
 * P0-05 extension-host feasibility probe.
 *
 * Three runs, each answering one question with observed evidence:
 *   A. loopback HTTP  - document_start ordering (MAIN vs ISOLATED) + all_frames
 *   B. loopback HTTPS - all_frames over https (self-signed, loopback only)
 *   C. removal probe  - mid-session ses.extensions.removeExtension()
 *
 * Loopback servers bind 127.0.0.1 only, on ephemeral ports, serving a fixed set
 * of routes. Run B uses a throwaway self-signed certificate generated by the
 * system openssl into the OS temp dir, and launches Electron with
 * --ignore-certificate-errors for that run ONLY, so Chromium will load a
 * loopback origin with an untrusted cert. No other run gets that flag, and the
 * certificate is deleted afterwards.
 *
 * Evidence channels: chrome.storage.local read back off disk (authoritative for
 * injection), the window title (used for run C, where the page itself reports
 * whether the extension is present), and [extension-host] lines on stdout.
 *
 * Safety: no arguments, no shell string interpolation (fixed argv only), no
 * remote debugging port, no code injected into Min. Writes only under the OS
 * temp directory plus one evidence file in docs/. Kills are scoped to spawned
 * PIDs. Servers are closed on every exit path.
 */

const { spawn, spawnSync } = require('child_process')
const fs = require('fs')
const http = require('http')
const https = require('https')
const os = require('os')
const path = require('path')

const ROOT = path.resolve(__dirname, '..')
const EVIDENCE_FILE = path.join(ROOT, 'docs', 'extension-probe.json')
const WIN32 = process.platform === 'win32'

const RUN_DIR = path.join(os.tmpdir(), 'min-agent-ext-probe')
const PROFILE_DIR = path.join(RUN_DIR, 'profile')
const CERT_DIR = path.join(RUN_DIR, 'cert')
/* Min appends "-development" to userData in dev mode (main/main.js:60). */
const EFFECTIVE_PROFILE = PROFILE_DIR + '-development'
const TAB_PARTITION = 'webcontent' /* persist:webcontent -> Partitions/webcontent */

const POLL_MS = 1500
const SETTLE_TIMEOUT_MS = 30000
const REMOVAL_SAMPLE_MS = 1500
const REMOVAL_SAMPLE_TOTAL_MS = 26000
const REMOVAL_DELAY_MS = 12000
const STORAGE_KEYS = ['minAgentProbe', 'minAgentFrames', 'minAgentOrder']

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms))

async function rmrfRetry (target, attempts = 12) {
  for (let i = 0; i < attempts; i++) {
    try { fs.rmSync(target, { recursive: true, force: true }) } catch (e) { /* retry */ }
    if (!fs.existsSync(target)) return true
    await sleep(750)
  }
  return !fs.existsSync(target)
}

function electronBinary () {
  const resolved = require('electron')
  if (typeof resolved !== 'string') {
    throw new Error('electron package did not resolve to a binary path')
  }
  return resolved
}

const PS_TITLES = [
  "$ErrorActionPreference='SilentlyContinue'",
  'Get-Process electron | ForEach-Object { if ($_.MainWindowTitle) { $_.MainWindowTitle } }'
].join('; ')

function windowTitles () {
  const res = spawnSync('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', PS_TITLES], { encoding: 'utf8', windowsHide: true })
  return (res.stdout || '').split('\n').map(s => s.trim()).filter(s => !!s)
}

function extractAfterKey (text, key) {
  const hits = []
  let from = 0
  while (true) {
    const idx = text.indexOf(key, from)
    if (idx === -1) break
    const start = idx + key.length
    let open = -1
    for (let i = start; i < Math.min(start + 8, text.length); i++) {
      if (text[i] === '{' || text[i] === '[') { open = i; break }
    }
    if (open !== -1) {
      const opener = text[open]
      const closer = opener === '{' ? '}' : ']'
      let depth = 0
      for (let i = open; i < text.length; i++) {
        if (text[i] === opener) depth++
        else if (text[i] === closer) {
          depth--
          if (depth === 0) {
            try { hits.push(JSON.parse(text.slice(open, i + 1))) } catch (e) { /* partial write */ }
            break
          }
        }
      }
    }
    from = start
  }
  return hits
}

function readExtensionStorage () {
  const base = path.join(EFFECTIVE_PROFILE, 'Partitions', TAB_PARTITION, 'Local Extension Settings')
  const out = { exists: fs.existsSync(base), extensionIds: [], probe: [], frames: [], order: [] }
  if (!out.exists) return out
  out.extensionIds = fs.readdirSync(base)
  for (const id of out.extensionIds) {
    const dir = path.join(base, id)
    let files = []
    try { files = fs.readdirSync(dir) } catch (e) { continue }
    for (const f of files) {
      if (!/\.(log|ldb)$/.test(f)) continue
      try {
        const raw = fs.readFileSync(path.join(dir, f)).toString('latin1')
        for (const k of STORAGE_KEYS) {
          for (const h of extractAfterKey(raw, k)) {
            out[k === 'minAgentProbe' ? 'probe' : k === 'minAgentFrames' ? 'frames' : 'order'].push(...(Array.isArray(h) ? h : [h]))
          }
        }
      } catch (e) { /* unreadable shard */ }
    }
  }
  return out
}

/* ---------- pages ---------- */

const PAGE_HEAD = [
  '<head><meta charset="utf-8">',
  '<script>',
  'window.__minAgentSeq = window.__minAgentSeq || [];',
  "window.__minAgentSeq.push('page-head');",
  'document.documentElement.dataset.pageSawIso =',
  "  (document.documentElement.dataset.minAgentExtension === 'document-start') ? 'yes' : 'no';",
  'document.documentElement.dataset.pageSawMain =',
  "  (window.__minAgentSeq[0] === 'ext-main-document-start') ? 'yes' : 'no';",
  '</script>'
].join('\n')

const PROBE_HTML = ['<!doctype html>', '<html>', PAGE_HEAD,
  '<title>P0-05 probe</title>',
  '<body><p>Min Agent P0-05 probe page</p>',
  '<iframe src="/frame.html" width="320" height="120"></iframe>',
  '</body></html>', ''].join('\n')

const FRAME_HTML = '<!doctype html>\n<html>\n<head><meta charset="utf-8"><title>P0-05 frame</title></head>\n<body><p>probe frame</p></body>\n</html>\n'

/* Run C page: reloads itself so a post-removal document is produced without
 * touching Min. The page reports the extension's presence itself, so absence is
 * observable even though the extension is gone. */
const RELOAD_HTML = ['<!doctype html>', '<html>',
  '<head><meta charset="utf-8">',
  '<meta http-equiv="refresh" content="5">',
  '<script>',
  'function report () {',
  "  var iso = (document.documentElement.dataset.minAgentExtension === 'document-start') ? 'yes' : 'no';",
  "  var v = getComputedStyle(document.documentElement).getPropertyValue('--min-agent-css-marker').trim();",
  "  var css = (v === 'rgb(251, 191, 36)') ? 'yes' : 'no';",
  "  var main = (window.__minAgentMainWorldRan === true) ? 'yes' : 'no';",
  "  document.title = 'PROBE iso=' + iso + ' css=' + css + ' main=' + main;",
  '}',
  'report();',
  "if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', report) }",
  '</script></head>',
  '<body><p>Min Agent P0-05 removal probe (reloads every 5s)</p></body></html>', ''].join('\n')

/* ---------- servers ---------- */

function serve (routes, opts) {
  return new Promise(function (resolve, reject) {
    const handler = function (req, res) {
      const body = routes[req.url]
      if (!body) { res.writeHead(404); res.end('not found'); return }
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' })
      res.end(body)
    }
    const server = opts.key ? https.createServer({ key: opts.key, cert: opts.cert }, handler) : http.createServer(handler)
    server.on('error', reject)
    server.listen(0, '127.0.0.1', function () { resolve({ server: server, port: server.address().port }) })
  })
}

function makeSelfSignedCert () {
  fs.mkdirSync(CERT_DIR, { recursive: true })
  const keyPath = path.join(CERT_DIR, 'key.pem')
  const certPath = path.join(CERT_DIR, 'cert.pem')
  const res = spawnSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-keyout', keyPath, '-out', certPath,
    '-days', '1', '-nodes', '-subj', '/CN=127.0.0.1', '-addext', 'subjectAltName=IP:127.0.0.1'],
  { encoding: 'utf8', windowsHide: true })
  if (res.status !== 0 || !fs.existsSync(certPath)) {
    throw new Error('openssl self-signed cert failed: ' + ((res.stderr || '') + (res.stdout || '')).trim().slice(0, 300))
  }
  return { key: fs.readFileSync(keyPath), cert: fs.readFileSync(certPath) }
}

/* ---------- launch ---------- */

async function launchOnce (bin, targetUrl, label, extraArgs) {
  const args = ['.', '--development-mode', '--user-data-dir=' + PROFILE_DIR].concat(extraArgs || []).concat([targetUrl])
  const proc = spawn(bin, args, { cwd: ROOT, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] })
  const out = []
  proc.stdout.on('data', d => out.push(String(d)))
  proc.stderr.on('data', d => out.push(String(d)))

  const deadline = Date.now() + SETTLE_TIMEOUT_MS
  let title = null
  while (Date.now() < deadline) {
    await sleep(POLL_MS)
    const titles = windowTitles()
    title = titles.find(t => t.startsWith('EXT ')) || titles.find(t => t.includes('Min')) || null
    if (title && title.startsWith('EXT ')) break
  }
  await sleep(4000)

  const kill = WIN32
    ? spawnSync('taskkill.exe', ['/F', '/T', '/PID', String(proc.pid)], { encoding: 'utf8', windowsHide: true })
    : (proc.kill('SIGTERM'), { status: null })
  await sleep(2000)

  const joined = out.join('')
  return {
    label: label,
    rootPid: proc.pid,
    treeKillExit: kill.status,
    title: title,
    extensionHostLog: joined.split('\n').filter(l => l.includes('[extension-host]')).map(l => l.trim()),
    manifestErrors: joined.split('\n').filter(l => /Manifest|Extensions API|not supported|Uncaught/i.test(l)).map(l => l.trim()).slice(0, 20),
    storage: readExtensionStorage()
  }
}

async function runRemovalProbe (bin, url) {
  const args = ['.', '--development-mode', '--user-data-dir=' + PROFILE_DIR, url]
  const proc = spawn(bin, args, { cwd: ROOT, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] })
  const out = []
  proc.stdout.on('data', d => out.push(String(d)))
  proc.stderr.on('data', d => out.push(String(d)))

  const samples = []
  const t0 = Date.now()
  while (Date.now() - t0 < REMOVAL_SAMPLE_TOTAL_MS) {
    await sleep(REMOVAL_SAMPLE_MS)
    samples.push({ tMs: Date.now() - t0, title: windowTitles()[0] || null })
  }

  const kill = WIN32
    ? spawnSync('taskkill.exe', ['/F', '/T', '/PID', String(proc.pid)], { encoding: 'utf8', windowsHide: true })
    : (proc.kill('SIGTERM'), { status: null })
  await sleep(2000)

  const joined = out.join('')
  return {
    label: 'removal probe',
    rootPid: proc.pid,
    treeKillExit: kill.status,
    samples: samples,
    extensionHostLog: joined.split('\n').filter(l => l.includes('[extension-host]')).map(l => l.trim())
  }
}

function writeProfile (withRemoveProbe) {
  fs.mkdirSync(EFFECTIVE_PROFILE, { recursive: true })
  const settings = { experimentalExtensionHost: true }
  if (withRemoveProbe) {
    settings.experimentalExtensionRemoveProbe = REMOVAL_DELAY_MS
  }
  fs.writeFileSync(path.join(EFFECTIVE_PROFILE, 'settings.json'), JSON.stringify(settings), 'utf8')
}

async function main () {
  const report = {
    task: 'P0-05 extension-host feasibility',
    startedAt: new Date().toISOString(),
    platform: process.platform + ' ' + process.arch,
    node: process.version,
    electron: (() => { try { return require('electron/package.json').version } catch (e) { return 'unknown' } })(),
    workspace: path.basename(ROOT),
    runs: []
  }

  await rmrfRetry(RUN_DIR)

  const bin = electronBinary()
  const servers = []

  try {
    /* ---- Run A: loopback HTTP ---- */
    writeProfile(false)
    const httpSrv = await serve({ '/probe.html': PROBE_HTML, '/frame.html': FRAME_HTML }, {})
    servers.push(httpSrv)
    const httpUrl = 'http://127.0.0.1:' + httpSrv.port + '/probe.html'
    report.runs.push(await launchOnce(bin, httpUrl, 'A loopback http'))

    /* ---- Run B: loopback HTTPS, self-signed, cert errors ignored for this run only ---- */
    const tls = makeSelfSignedCert()
    const httpsSrv = await serve({ '/probe.html': PROBE_HTML, '/frame.html': FRAME_HTML }, tls)
    servers.push(httpsSrv)
    const httpsUrl = 'https://127.0.0.1:' + httpsSrv.port + '/probe.html'
    report.httpsRun = { url: 'https://127.0.0.1:<ephemeral>/probe.html', cert: 'throwaway self-signed, CN=127.0.0.1, SAN IP:127.0.0.1, 1 day', flag: '--ignore-certificate-errors (this run only)' }
    await rmrfRetry(EFFECTIVE_PROFILE)
    writeProfile(false)
    report.runs.push(await launchOnce(bin, httpsUrl, 'B loopback https', ['--ignore-certificate-errors']))

    /* ---- Run C: mid-session removeExtension ---- */
    await rmrfRetry(EFFECTIVE_PROFILE)
    writeProfile(true)
    const reloadSrv = await serve({ '/reload.html': RELOAD_HTML }, {})
    servers.push(reloadSrv)
    report.runs.push(await runRemovalProbe(bin, 'http://127.0.0.1:' + reloadSrv.port + '/reload.html'))
  } finally {
    servers.forEach(s => s.server.close())
    report.serversClosed = true
  }

  const frames = []
  const orders = []
  for (const r of report.runs) {
    if (!r.storage) continue
    for (const f of r.storage.frames) frames.push({ run: r.label, url: f.senderUrl, senderFrameId: f.senderFrameId, isTop: f.isTop, css: f.cssMarkerSeen })
    for (const o of r.storage.order) orders.push({ run: r.label, url: o.url, senderFrameId: o.senderFrameId, pageSawIsolated: o.pageSawIsolated, pageSawMainWorld: o.pageSawMainWorld, mainWorldMarker: o.mainWorldMarker })
  }
  report.frameRecords = frames
  report.orderRecords = orders
  report.httpsFrames = frames.filter(f => f.run === 'B loopback https')
  report.httpsNonTopFrames = report.httpsFrames.filter(f => f.senderFrameId !== 0)
  report.removalRun = report.runs.find(r => r.label === 'removal probe') || null

  await rmrfRetry(RUN_DIR)
  report.cleanup = { runDirRemoved: !fs.existsSync(RUN_DIR) }
  report.finishedAt = new Date().toISOString()

  fs.writeFileSync(EVIDENCE_FILE, JSON.stringify(report, null, 2), 'utf8')

  console.log('--- A/B frames ---')
  frames.forEach(f => console.log(JSON.stringify(f)))
  console.log('\n--- ordering ---')
  orders.forEach(o => console.log(JSON.stringify(o)))
  console.log('\n--- https non-top-frame injections: ' + report.httpsNonTopFrames.length + ' ---')
  console.log('\n--- removal probe: host log ---')
  if (report.removalRun) report.removalRun.extensionHostLog.forEach(l => console.log('  ' + l))
  console.log('\n--- removal probe: title samples ---')
  if (report.removalRun) report.removalRun.samples.forEach(s => console.log('  t=' + s.tMs + 'ms  ' + s.title))
  console.log('\nevidence: ' + EVIDENCE_FILE)
  return 0
}

main().then(code => process.exit(code)).catch(e => {
  console.error('extension probe error: ' + e.message)
  try { fs.rmSync(RUN_DIR, { recursive: true, force: true }) } catch (ignored) {}
  process.exit(2)
})
